"""Rolling volatility from earlier returns (RISK-02)."""

from __future__ import annotations

import statistics

from risk.types import Returns, VolSeries


def rolling_vol(returns: Returns, window: int) -> VolSeries:
    """The sample standard deviation of the `window` returns before each date, never its own.

    Spine version: the stdev of all earlier returns, None until `window` of them exist.

    Raises ValueError if `window` < 2.
    """
    if window < 2:
        raise ValueError(f"window must be at least 2, got {window}")
    values = {ticker: _expanding_stdev(returns.values[ticker], window) for ticker in returns.tickers}
    return VolSeries(returns=returns, window=window, annualized=False, values=values)


def _expanding_stdev(series: tuple[float, ...], window: int) -> tuple[float | None, ...]:
    return tuple(
        statistics.stdev(series[:i]) if i >= window else None for i in range(len(series))
    )

